1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.time.LocalDate;
4	
5	/**
6	 * Shared knowledge of the owner {@code customerCode} string format, kept in one place so every
7	 * value derived from it stays consistent. The customerCode is {@code <REGION>-<HASH8>}, where
8	 * {@code REGION} is the region code derived from the owner's postcode (see
9	 * {@link Localities#locality(String, String)}) and {@code HASH8} is the first 8 upper-case hex
10	 * characters of the SHA-256 digest over the normalized (E.164) telephone concatenated with the
11	 * last name (see {@link Sha256#hexPrefix(String, int)}).
12	 *
13	 * <p>It is a stable identity carrying no sequence number; when the {@link #base base} value
14	 * collides with an existing owner's customerCode the producer appends {@code -<n>} (see
15	 * {@code org.springframework.samples.petclinic.rest.function.owner.AssignOwnerCustomerCode}).
16	 * Every value that follows from the customerCode — the {@link #membershipNumber membership
17	 * number}, the create audit line and the {@link Localities#localityOf locality/timezone} read
18	 * back from its {@link #regionOf region} prefix — is built through this class so they all agree
19	 * on the one format.
20	 */
21	public final class CustomerCode {
22	
23	    private CustomerCode() {
24	    }
25	
26	    /**
27	     * The base {@code <REGION>-<HASH8>} customerCode for a region and the owner's identity
28	     * inputs, before any collision suffix. {@code lastName} is treated as empty when null.
29	     */
30	    public static String base(String region, String normalizedTelephone, String lastName) {
31	        String name = lastName == null ? "" : lastName;
32	        return region + "-" + Sha256.hexPrefix(normalizedTelephone + name, 8);
33	    }
34	
35	    /**
36	     * The region encoded in a stored customerCode — the {@code REGION} prefix before the first
37	     * {@code '-'} — or {@code null} when the code is absent or carries no region prefix (e.g.
38	     * legacy records).
39	     */
40	    public static String regionOf(String customerCode) {
41	        if (customerCode == null) {
42	            return null;
43	        }
44	        int dash = customerCode.indexOf('-');
45	        return dash > 0 ? customerCode.substring(0, dash) : null;
46	    }
47	
48	    /**
49	     * The membership number {@code <customerCode>-M<YY>}, where {@code YY} is the two-digit
50	     * fiscal year of the registration date (see {@link FiscalYear#twoDigit(LocalDate)}), or
51	     * {@code null} when the customerCode or registration date is absent.
52	     */
53	    public static String membershipNumber(String customerCode, LocalDate registrationDate) {
54	        if (customerCode == null || registrationDate == null) {
55	            return null;
56	        }
57	        return customerCode + "-M" + FiscalYear.twoDigit(registrationDate);
58	    }
59	}
