3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	/**
9	 * Shared SHA-256 hex derivation. Several owner-identity values are the hex encoding of a
10	 * SHA-256 digest — the full lower-case digest (the duplicate-detection identity key), the
11	 * first 12 upper-hex chars (the household id, see
12	 * {@code org.springframework.samples.petclinic.rest.function.owner.OwnerHousehold}) and the
13	 * first 8 upper-hex chars (the customerCode hash, see {@link CustomerCode#base}) — so the
14	 * digest itself is computed here once rather than reimplemented per call site.
15	 */
16	public final class Sha256 {
17	
18	    private Sha256() {
19	    }
20	
21	    /** Full lower-case hex of the SHA-256 digest over the UTF-8 bytes of {@code input}. */
22	    public static String hex(String input) {
23	        try {
24	            byte[] digest = MessageDigest.getInstance("SHA-256")
25	                    .digest(input.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder sb = new StringBuilder(digest.length * 2);
27	            for (byte b : digest) {
28	                sb.append(String.format("%02x", b));
29	            }
30	            return sb.toString();
31	        }
32	        catch (NoSuchAlgorithmException e) {
33	            throw new IllegalStateException(e);
34	        }
35	    }
36	
37	    /** The first {@code n} upper-case hex characters of the SHA-256 digest of {@code input}. */
38	    public static String hexPrefix(String input, int n) {
39	        return hex(input).substring(0, n).toUpperCase(Locale.ROOT);
40	    }
41	}
