1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Derives fiscal-year values from a date. The fiscal year starts on 1 July: a date on or
8	 * after 1 July belongs to the fiscal year ending the following calendar year, otherwise it
9	 * belongs to the fiscal year ending in its own calendar year. The fiscal year is named by
10	 * the calendar year in which it ends (so 1 July 2026 to 30 June 2027 is fiscal year 2027).
11	 *
12	 * <p>Callers pass the business-day-adjusted registration date (see {@link BusinessDays}), so
13	 * every fiscal-year-derived value — the {@code fiscalYear} label and the membership number's
14	 * year segment — follows from the adjusted date.
15	 */
16	public final class FiscalYear {
17	
18	    /** The month the fiscal year starts on. */
19	    private static final Month FISCAL_YEAR_START = Month.JULY;
20	
21	    private FiscalYear() {
22	    }
23	
24	    /**
25	     * The fiscal year the given date falls in, named by the calendar year in which the
26	     * fiscal year ends.
27	     */
28	    public static int of(LocalDate date) {
29	        int year = date.getYear();
30	        return date.getMonthValue() >= FISCAL_YEAR_START.getValue() ? year + 1 : year;
31	    }
32	
33	    /**
34	     * The two-digit fiscal year {@code YY} — the last two digits of the fiscal year (see
35	     * {@link #of(LocalDate)}), zero-padded, e.g. {@code 27}. The shared year segment of both
36	     * the {@link #label(LocalDate) FY label} and the membership number.
37	     */
38	    public static String twoDigit(LocalDate date) {
39	        return String.format("%02d", of(date) % 100);
40	    }
41	
42	    /**
43	     * The fiscal year label {@code FY<YY>}, where {@code YY} is the last two digits of the
44	     * fiscal year (see {@link #of(LocalDate)}), e.g. {@code FY27}.
45	     */
46	    public static String label(LocalDate date) {
47	        return "FY" + twoDigit(date);
48	    }
49	}
