3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.rest.function.common.Sha256;
6	import org.springframework.samples.petclinic.rest.function.common.Soundex;
7	
8	/**
9	 * The single derived key used to detect duplicate owners. It is the full lower-case SHA-256 hex
10	 * digest over {@code normalizedTelephone + "|" + lowerEmail + "|" + soundex(lastName)}:
11	 *
12	 * <ul>
13	 *   <li>the telephone in canonical E.164 form (see {@link OwnerTelephone});</li>
14	 *   <li>the email lower-cased, or empty when absent;</li>
15	 *   <li>the last name folded to its {@link Soundex} code, so phonetically equal surnames collapse.</li>
16	 * </ul>
17	 *
18	 * <p>Creation is rejected with 409 only when a new owner's WHOLE identityKey equals an existing
19	 * (non-deleted) owner's — see {@link EnsureUniqueOwnerIdentity}. Because the telephone is part of
20	 * the key, two owners with the same last name and postcode but different telephones have different
21	 * keys: they are not a hard duplicate but a soft match (see {@link AssignOwnerPossibleDuplicate}).
22	 */
23	public final class OwnerIdentityKey {
24	
25	    private OwnerIdentityKey() {
26	    }
27	
28	    /** The identityKey of a stored owner, from its telephone, email and last name. */
29	    public static String of(org.springframework.samples.petclinic.model.Owner owner) {
30	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
31	    }
32	
33	    /** The identityKey for the given telephone, email and last name. */
34	    public static String of(String telephone, String email, String lastName) {
35	        String tel = OwnerTelephone.canonical(telephone);
36	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
37	        String soundex = Soundex.of(lastName);
38	        return Sha256.hex(tel + "|" + mail + "|" + soundex);
39	    }
40	}
