3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request whose {@link OwnerIdentityKey} equals that of an existing
10	 * (non-deleted) owner, responding 409. The identityKey is the SHA-256 hex over the normalized
11	 * telephone, lower-cased email and Soundex last name, so this is the single duplicate-detection
12	 * check: there is no longer a separate household-duplicate block.
13	 *
14	 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
15	 * different telephones have different keys and are both allowed (the second is instead flagged as a
16	 * possible duplicate — see {@link AssignOwnerPossibleDuplicate}).
17	 *
18	 * <p>Runs after {@link ValidateOwnerFields}, so the email-domain blocklist and telephone
19	 * normalization have already been applied to the request. A soft-deleted owner no longer blocks a
20	 * new one.
21	 */
22	public class EnsureUniqueOwnerIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateOwnerIdentityException {
26	        String identityKey = OwnerIdentityKey.of(
27	                request.getTelephone(), request.getEmail(), request.getLastName());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (existing.isDeleted()) {
30	                continue; // a soft-deleted owner no longer blocks a new one
31	            }
32	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
33	                throw new DuplicateOwnerIdentityException(identityKey);
34	            }
35	        }
36	    }
37	}
