2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.rest.function.common.Sha256;
6	
7	/**
8	 * Shared derivation of an owner's household identity. The {@code householdId} is now
9	 * <em>deterministic</em>: the first 12 hex characters of SHA-256 over
10	 * {@code normalizedLastName + "|" + postcode}. Owners with the same last name (compared
11	 * case-insensitively with collapsed whitespace) and the same postcode therefore resolve to
12	 * the same householdId automatically, without any creation-order back-fill.
13	 *
14	 * <p>Used by {@link AssignOwnerHousehold} (which stamps the id onto a new owner), by
15	 * {@link EnsureUniqueOwnerIdentity} (which blocks a second owner of an existing household) and
16	 * by {@link AssignOwnerPossibleDuplicate} (which treats fellow household members as declared,
17	 * not suspected, duplicates), so all three agree on exactly what a household is.
18	 */
19	final class OwnerHousehold {
20	
21	    private OwnerHousehold() {
22	    }
23	
24	    /**
25	     * The deterministic {@code householdId} for the given last name and postcode, or
26	     * {@code null} when no postcode is supplied (an owner with no postcode has no household).
27	     */
28	    static String idFor(String lastName, String postcode) {
29	        if (postcode == null || postcode.isBlank()) {
30	            return null;
31	        }
32	        return id(normalizeName(lastName), postcode.trim());
33	    }
34	
35	    /** Stable 12-char upper-hex identifier derived from the deterministic household key. */
36	    static String id(String normalizedLastName, String postcode) {
37	        return Sha256.hexPrefix(normalizedLastName + "|" + postcode, 12);
38	    }
39	
40	    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
41	    static String normalizeName(String value) {
42	        if (value == null) {
43	            return "";
44	        }
45	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
46	    }
47	}
