6	/**
7	 * Stamps the deterministic {@code householdId} onto a newly built owner — the first 12 hex
8	 * characters of SHA-256 over the normalized last name and the postcode (see
9	 * {@link OwnerHousehold}). Because the value is derived purely from (lastName, postcode) every
10	 * member of a household resolves to the same identifier regardless of creation order, so no
11	 * back-fill of earlier members is needed.
12	 *
13	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}. An owner with no postcode has
14	 * no household and keeps a {@code null} householdId. The same derivation feeds the duplicate
15	 * block in {@link EnsureUniqueOwnerIdentity} and the household size in
16	 * {@link AssignOwnerHouseholdSize}.
17	 */
18	public class AssignOwnerHousehold {
19	
20	    public void service(@Val Owner owner) {
21	        owner.setHouseholdId(OwnerHousehold.idFor(owner.getLastName(), owner.getPostcode()));
22	    }
23	}
