5	/**
6	 * Validates an owner's optional {@code postcode}. A postcode is validated only when present:
7	 * an absent (null or blank) postcode is accepted, keeping the create/update request contract
8	 * backward-compatible. When present it must be exactly 4 digits and, for a city whose region is
9	 * in the fixed table (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), fall within that region's
10	 * range. A city with no known region accepts any 4-digit postcode.
11	 */
12	final class OwnerPostcode {
13	
14	    private OwnerPostcode() {
15	    }
16	
17	    /**
18	     * Validate the supplied postcode for the given city, throwing when it is present but invalid.
19	     * Does nothing when the postcode is absent.
20	     */
21	    static void validate(String postcode, String city) throws InvalidOwnerPostcodeException {
22	        if (postcode == null || postcode.isBlank()) {
23	            return; // optional when absent
24	        }
25	        if (!postcode.matches("[0-9]{4}")) {
26	            throw new InvalidOwnerPostcodeException("Postcode must be 4 digits, but was: '" + postcode + "'");
27	        }
28	        int[] range = Localities.postcodeRange(Localities.region(city));
29	        if (range == null) {
30	            return; // city with no known region accepts any 4-digit postcode
31	        }
32	        int value = Integer.parseInt(postcode);
33	        if (value < range[0] || value > range[1]) {
34	            throw new InvalidOwnerPostcodeException("Postcode '" + postcode + "' is out of range "
35	                    + range[0] + "-" + range[1] + " for city '" + city + "'");
36	        }
37	    }
38	}
